INSERT INTO vi_business_base (company_id, code, name, kind, capital_basis, driver1_label, driver1_unit, driver2_label, driver2_unit, driver_scale, boundary, sort) VALUES ((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'B1', '林浆纸一体化', '经营', '企业', NULL, NULL, NULL, NULL, NULL, '文化用纸、包装纸、生活用纸、溶解浆与化机浆；国内山东、广西基地与老挝林浆基地。', 1) ON CONFLICT (company_id, code) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, capital_basis = EXCLUDED.capital_basis, driver1_label = EXCLUDED.driver1_label, driver1_unit = EXCLUDED.driver1_unit, driver2_label = EXCLUDED.driver2_label, driver2_unit = EXCLUDED.driver2_unit, driver_scale = EXCLUDED.driver_scale, boundary = EXCLUDED.boundary, sort = EXCLUDED.sort;
