INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'J-IC', '期初投入资本与资产负债桥（统一估值引擎）', '已形成建议', '2026-06-30 归母权益 315.3 亿元，减去资产负债桥里按账面计的项目净额 -189.4 亿元（货币资金、带息负债、少数股东权益；负数＝负债多于资产），得到经营业务的期初投入资本 504.7 亿元。业务资本和资产负债桥合起来正好是报表的归母权益，没有重复或遗漏（自动检查 V09 对账）。', '投入资本是资产价值（未填重置成本时）和 ROIC 的分母；资本增加从自由现金流里扣。', '估值假设·期初投入资本；资产负债桥 N 项', '新的半年报或年报出来后，按同一口径更新截至日与金额。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'J-NORM', '正常化经营利润率（盈利能力价值用）', '已形成建议', '2016—2025 年 10 年的平均经营利润率 12.9%（(利润总额＋财务费用−投资收益)÷营业收入），代表一个完整周期的中枢。', '盈利能力价值＝第一个完整年度收入×正常化经营利润率×(1−税率)÷门槛；只影响“三层价值”的中间一层，不影响全价值。', '估值假设·正常化经营利润率', '行业格局或公司成本结构发生持久变化（不是周期波动）时改用新的中枢。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '002078.SZ'), 'J-PROB', '情景概率 25% / 50% / 25%（待确认）', '已形成建议', '还没有逐一论证情景概率，先按悲观 25%、基准 50%、乐观 25% 给出概率加权价值；要改时写清楚为什么某一情景更可能。', '只影响概率加权每股价值，不影响各情景本身。', '情景·情景概率', '有证据表明某一情景的可能性明显更高或更低。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
